package com.example.application_service.repository;import com.example.application_service.entity.*;import jakarta.persistence.LockModeType;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.Instant;import java.util.*;import java.util.UUID;
public interface OutboxEventRepository extends JpaRepository<OutboxEvent,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select e from OutboxEvent e where ((e.status in :ready and e.nextAttemptAt<=:now) or (e.status=:working and e.lockedAt<:stale)) order by e.createdAt")List<OutboxEvent> lockBatch(@Param("ready")Collection<OutboxStatus> ready,@Param("working")OutboxStatus working,@Param("now")Instant now,@Param("stale")Instant stale,Pageable pageable);long countByStatus(OutboxStatus status);}
